package com.clothingstore;
import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserAccountRepository users; JwtAuthFilter(JwtService jwt,UserAccountRepository users){this.jwt=jwt;this.users=users;} @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer ")){try{UserAccount user=users.findByEmail(jwt.email(header.substring(7))).filter(UserAccount::isEnabled).orElse(null);if(user!=null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole()))));}catch(JwtException ignored){}}chain.doFilter(request,response);} }
